// glj-eve: the glj eve runs on (hosts.edn :glj). It is glojure's own
// gljdeps main template (internal/deps/glj.go:mainTemplate in glojure
// v0.7.22) with one more blank import: eveglj/gljimports, the package map
// generated by glojure's cmd/gen-import-interop for syscall, unsafe and the
// eve packages (region, types, host). pkgmap.SetLoader appends that registrar
// to the stock one (pkg/glj imports pkg/gen/gljimports), so every stock
// package stays reachable.
package main

import (
	"os"
	"runtime/debug"
	"runtime/pprof"

	"github.com/glojurelang/glojure/pkg/gljmain"
	_ "github.com/glojurelang/glojure/pkg/gljmain/interactive"

	_ "eveglj/gljimports"
)

func main() {
	// glojure sets the collector's target to 400 when GOGC is unset (pkg/lang/gc.go: fewer collections of its
	// short-lived boxed values). eve's regions are large, long-lived Go slices, and at 400 the heap may grow to five
	// times the live data before a collection: bb test:glj peaked at 7.1 GB resident with 1.4 GB live. Go's own
	// default, 100, held it to 1.0 GB for 2% more time (217 s -> 222 s, 2026-10-20 ET). GOGC in the environment still
	// decides.
	if os.Getenv("GOGC") == "" {
		debug.SetGCPercent(100)
	}
	// GLJ_CPUPROFILE=<file>: Go's CPU profile of the run, written when glj returns (a script or -e form ends normally;
	// `go tool pprof -top glj-eve <file>`) — what the interpreter spends its time on, by Go function.
	if path := os.Getenv("GLJ_CPUPROFILE"); path != "" {
		if f, err := os.Create(path); err == nil && pprof.StartCPUProfile(f) == nil {
			defer func() { pprof.StopCPUProfile(); f.Close() }()
		}
	}
	gljmain.Main(os.Args[1:])
}
